        contextWrong: "「他是在请求原谅。」宾斯二世的声音低沉了一些，「教皇开除了他的教籍——在中世纪，这意味着任何基督徒都可以拒绝服从他的统治。亨利四世在卡诺莎城堡外的大雪里赤足站了三天，才让教皇收回成命。你们想想——一个国王，跪在一个老人面前——这就是教会权力的真实写照。」",
        context: "「1077年——卡诺莎之辱。」宾斯二世在黑板上写下这个年份。「亨利四世——神圣罗马帝国的皇帝——与教皇格里高利七世发生了冲突。亨利试图控制教会主教的任命权，教皇回应：开除亨利教籍。在中世纪，被开除教籍的国王就失去了统治的合法性——他的臣民不再有义务服从他。」他停顿了一下，「亨利四世别无选择，只能在大雪天翻越阿尔卑斯山，在教皇居住的卡诺莎城堡外赤足站了三天，请求宽恕。教皇让他等了三天才接见他——这是一场精心设计的权力展示。」他合上圣经，「这告诉我们：在中世纪，王权之上还有一种更高的权威——教会的权威。」"
