        contextWrong: "「是马丁·路德的著作被大量印刷。」宾斯二世解释道，「1517年路德把他的九十五条论纲钉在教堂门上——有人把它拿下来送到了印刷厂。几周之内，他的思想传遍了德国。几个月之内，传遍了欧洲。教会有钱有军队——但印刷机可以让一个修道士的声音比教皇的命令传得更远更快。」",
