        contextRight: "「对！他想要一条通往东方——印度和中国——的新航路。」宾斯二世点头。「当时东方的香料和丝绸经过陆路运到欧洲，价格贵得离谱。哥伦布想：如果向西走，绕过地球的背面到达东方——那就比绕过非洲近多了。他算错了，但恰恰因为这个错误，他发现了美洲。」",
        contextWrong: "「他是想找一条通往东方的新航路。」宾斯二世纠正道。「当时欧洲人去东方走陆路——经过中东——路线长、费用高、而且被奥斯曼帝国控制。哥伦布想从西边走，绕过地球背面到达日本和中国。他低估了地球的周长——但他的错误歪打正着，让他发现了一片欧洲人完全不知道的大陆。」",
        context: "「哥伦布在1492年做的事情，本质上是一次赌博。」宾斯二世在模型船边来回踱步。「他向西航行横跨大西洋——当时大多数有经验的水手都认为他疯了，因为正确的距离比他以为的远得多。但他对自己的计算深信不疑——或者说，他固执到愿意拿三条船和九十条人命去验证。1492年10月12日——」他指向地图上的巴哈马群岛，「他看到了陆地。他以为那是日本附近的某个岛屿。实际上，那是一个欧洲人完全不知道的全新大陆。认识到自己发现的是一块'新大陆'——而不是亚洲——这件事花了哥伦布和他的时代很多年。他到死都认为自己去的是亚洲。但他死后，其他探险家很快意识到：这是一片全新的世界——欧洲人从来不知道它的存在。」"
