        contextWrong: "「是马铃薯。」宾斯二世在黑板上写下这个词。「还有玉米、番茄、辣椒、可可、烟草——全都是美洲原来没有的作物被传入欧洲的。反过来，欧洲人把小麦、马、牛、羊带到了美洲——以及最致命的礼物：天花等传染病。美洲原住民对欧洲的疾病没有任何免疫力——一些地区的人口死亡率高达90%。这不是征服——这是一场被疾病加速的征服。」",
