          leadIn: "「在蒸汽机之前——如果你想纺线、织布、磨面粉、锯木头——你靠的是什么？」宾斯二世环视教室，「水车？风车？马？你自己的手？所有动力都受限于自然条件——水车只能在河边，风车得有风，马得吃草。」",
          text: "蒸汽机对工业最根本的影响是什么？",
          options: ["让产品更美观", "提供不受自然条件限制的持续动力", "替代所有手工技术", "让工人更舒适"],
