            "      女工约 5-8 先令/周",
            "      童工约 1-3 先令/周",
            "童工年龄：低至 5-7 岁",
            "惩罚：迟到罚款 · 出错挨打",
            "环境：噪音 · 粉尘 · 高温 · 通风极差",
            "",
