    opening: "「工人阶级开始组织起来了——」宾斯二世举起那份厚重的请愿书复制件，「为自己的权利而斗争。宪章运动——」他拍了拍请愿书，「是工人阶级第一次大规模的独立政治行动。他们要求的是世界上最基本的东西：选举权。」",
    lessonSummary: "今天这节课让人振奋也让人沮丧：宪章运动——工人们史上第一次大规模的政治动员——三百万人签名要求普选权。议会拒绝了。运动失败了。但他们的要求——普选权、秘密投票、议员薪俸——在后来的几十年里一个一个实现了。改革不是一次运动完成的——是一代又一代人接力完成的。",
    nextLessonPreview: "下一课我们看维多利亚时代的全貌——大英帝国的鼎盛时代，进步与矛盾并存的时代。",
