          text: "索姆河战役最突出地体现了第一次世界大战的什么特征？",
          options: ["A. 速战速决的闪电战术", "B. 工业化武器导致的大规模伤亡与战场僵局", "C. 海战的决定性作用", "D. 骑兵冲锋的辉煌胜利"],
