        contextRight: "「太好了！」宾斯二世拍了一下桌子，「一个是当时的记录——一个是后来的解释。士兵的家信告诉你他当时怎么想的——那是真实的声音。但你不能只靠一封信就得出结论——因为他的视角有限。历史学家的书综合了成千上万份这样的史料——但他的分析和结论也可能受到他自己的立场影响。」",
