        context: "「史料的可靠性不是绝对的——取决于你的问题。」宾斯二世在四个问题旁边画了四个圈。「一份官方声明——对研究政府想要公众相信什么——极有价值。对研究政府内部真实的讨论——毫无价值。一份私人日记——对研究个人的真实想法——极有价值。但记忆会出错——日记可能是在事件几天后才补写的——作者可能有意美化自己。」他停顿了一下，「历史学家的工作不是找到'最可靠的'一份史料——而是把不同来源放在一起比较——找到一致之处和矛盾之处——然后做出有证据支撑的判断。史料批判——这是历史学的核心技能。」"
