          text: "研究外交档案最重要的价值是什么？",
          options: ["A. 记录条约签署的表面过程", "B. 揭示国家决策的内部逻辑与真实动机", "C. 美化政治领袖的历史形象", "D. 提供娱乐性的历史故事"],
