            "1913  埃米莉·戴维森在德比赛马场殉道",
            "1918  30岁以上女性获得投票权",
            "1928  与男性平等：21岁以上皆可投票",
            "",
            "手段：请愿 → 游行 → 绝食 → 破坏财产"
