          text: "后殖民理论主要批判的是什么？",
          options: ["A. 殖民地人民的文化落后性", "B. 以欧洲为中心的殖民主义历史叙事及其背后的权力关系", "C. 独立运动的激进手段", "D. 殖民地经济的发展模式"],
