    opening: "「这段话——」他指向黑板，「是我三十年前写的第一篇历史论文的第一段。」他停顿了一下，「我把它留着，是因为它提醒我：第一稿永远是不够好的，好的写作是修改出来的，不是一次写好的。」他转向全班，「历史写作——今天我们来谈它的基本要求。」",
    lessonSummary: "历史写作要求客观严谨、基于证据。学术语言需要准确、清晰、简洁，避免情绪化和模糊的表达。修改是写作过程的核心部分，而不是可以省略的步骤——反复修改和校对是提高写作质量的唯一方法。",
