          text: "历史写作区别于其他写作类型的核心特征是什么？",
          options: ["A. 越主观越好，展示个人情感", "B. 客观严谨，论点和描述都需要基于证据支撑", "C. 用尽量复杂的词汇显示学术水平", "D. 只描述事实，绝不作任何判断"],
